const skills = [
  {name:'api-design',description:'Shape consistent API contracts and review response patterns.',state:'active',scopes:['Codex','Claude Code'],tokens:3150,source:'Local folder',updated:'12 Oct 2026',body:'Use this skill when planning a public or internal API. Begin with the user task and the resource model. Describe status codes, error responses, and pagination before adding implementation details.'},
  {name:'code-review',description:'Find correctness, security, and maintainability issues in changes.',state:'active',scopes:['Codex','Claude Code','Agents'],tokens:2840,source:'Local folder',updated:'10 Oct 2026',body:'Review the diff against the surrounding code and its tests. Prioritize actionable findings. Explain the failure mode and point to the smallest relevant location.'},
  {name:'design-system',description:'Keep interface tokens, type, and interaction patterns consistent.',state:'divergent',scopes:['Codex','Claude Code'],tokens:4120,source:'Local folder',updated:'9 Oct 2026',body:'Use the existing project design decisions. Verify colors, typography, spacing, controls, and accessibility in rendered UI.'},
  {name:'documentation',description:'Write clear technical guides grounded in current behavior.',state:'active',scopes:['Codex'],tokens:1770,source:'Local folder',updated:'8 Oct 2026',body:'Write for the reader’s next action. Verify command examples and mark unknown behavior rather than inferring it from names.'},
  {name:'frontend-performance',description:'Profile and improve client-side loading and rendering.',state:'active',scopes:['Codex','Agents'],tokens:2460,source:'Local folder',updated:'6 Oct 2026',body:'Measure before changing code. Record the user-visible bottleneck, its reproduction path, and the before/after result.'},
  {name:'release-checklist',description:'Check packaging and release evidence before publishing.',state:'invalid',scopes:['Claude Code'],tokens:1890,source:'Local folder',updated:'3 Oct 2026',body:'Confirm the release branch, package contents, checksums, and required approvals. Stop if a required gate fails.'},
  {name:'security-audit',description:'Review trust boundaries and risky data flows.',state:'active',scopes:['Codex','Claude Code'],tokens:3590,source:'Local folder',updated:'1 Oct 2026',body:'Trace data from entry points to sensitive operations. Confirm assumptions with code or a reproducible test.'},
  {name:'test-automation',description:'Plan meaningful browser tests around user workflows.',state:'active',scopes:['Agents'],tokens:2380,source:'Local folder',updated:'28 Sep 2026',body:'Test observable outcomes, keyboard flows, and error recovery. Prefer stable selectors and isolated fixtures.'}
];
const state={view:'library',scope:'All scopes',filter:'all',query:'',selected:'design-system',tab:'overview',theme:'light'};
const $=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon=(name)=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const statusLabel={active:'Active',divergent:'Divergent',invalid:'Invalid',disabled:'Disabled'};
const status=kind=>`<span class="status ${kind}">${statusLabel[kind]}</span>`;
const pathFor=(scope,name)=>`~/.${scope==='Claude Code'?'claude':scope==='Codex'?'codex':'agents'}/skills/${name}/SKILL.md`;
const scopes=['All scopes','Codex','Claude Code','Agents'];
function visibleSkills(){return skills.filter(s=>(state.scope==='All scopes'||s.scopes.includes(state.scope))&&(state.filter==='all'||(state.filter==='attention'?['divergent','invalid'].includes(s.state):s.state==='active'))&&(!state.query||`${s.name} ${s.description} ${s.scopes.join(' ')} ${s.source}`.toLowerCase().includes(state.query)));}
function setStatus(text){$('#status-message').textContent=text;}
function renderScopes(){const counts=scopes.map(scope=>scope==='All scopes'?skills.reduce((n,s)=>n+s.scopes.length,0):skills.filter(s=>s.scopes.includes(scope)).length);$('#scope-total').textContent=`${counts[0]} instances`;$('#scope-list').innerHTML=scopes.map((scope,i)=>`<button class="scope-button ${scope===state.scope?'is-active':''}" type="button" data-scope="${escapeHtml(scope)}" aria-pressed="${scope===state.scope}"><span>${escapeHtml(scope)}</span><span>${counts[i]}</span></button>`).join('');$('#mobile-scope').innerHTML=scopes.map(scope=>`<option value="${escapeHtml(scope)}" ${scope===state.scope?'selected':''}>${escapeHtml(scope)}</option>`).join('');}
function renderList(){const visible=visibleSkills();$('#library-nav-count').textContent=skills.length;$('#visible-count').textContent=`${visible.length} ${visible.length===1?'skill':'skills'}`;$('#list-context').textContent=state.scope;$('#count-all').textContent=skills.filter(s=>state.scope==='All scopes'||s.scopes.includes(state.scope)).length;$('#count-attention').textContent=skills.filter(s=>(state.scope==='All scopes'||s.scopes.includes(state.scope))&&['divergent','invalid'].includes(s.state)).length;$('#count-active').textContent=skills.filter(s=>(state.scope==='All scopes'||s.scopes.includes(state.scope))&&s.state==='active').length;
  $('.filter-bar').querySelectorAll('[data-filter]').forEach(button=>{button.classList.toggle('is-active',button.dataset.filter===state.filter);button.setAttribute('aria-pressed',String(button.dataset.filter===state.filter));});
  if(!visible.length){$('#skill-list').innerHTML=`<li class="empty-list"><h2>No skills found</h2><p>Try a different search, state, or agent scope.</p><button class="button button-quiet" type="button" id="clear-filters">Clear filters</button></li>`;return;}
  $('#skill-list').innerHTML=visible.map(s=>`<li class="skill-item"><button class="skill-button ${s.name===state.selected?'is-selected':''}" type="button" data-skill="${escapeHtml(s.name)}" aria-current="${s.name===state.selected?'true':'false'}"><span class="skill-top"><span class="skill-name">${escapeHtml(s.name)}</span>${status(s.state)}</span><span class="skill-description">${escapeHtml(s.description)}</span><span class="skill-foot"><span class="skill-scope">${s.scopes.map(escapeHtml).join(' · ')}</span><span>${s.scopes.length} ${s.scopes.length===1?'copy':'copies'}</span></span></button></li>`).join('');}
function instanceRows(s){return s.scopes.map((scope,i)=>{let label=s.state==='divergent'&&i===1?'Different content':s.state==='invalid'?'Invalid frontmatter':'Matches selected';let path=pathFor(scope,s.name);return `<div class="instance-row"><div><div class="instance-name">${escapeHtml(scope)}</div><div class="instance-path">${escapeHtml(path)}</div><div class="instance-sub">Observed file · ${escapeHtml(s.updated)}</div></div><div class="instance-status">${s.state==='invalid'?status('invalid'):s.state==='divergent'&&i===1?status('divergent'):status('active')}<div class="instance-sub">${label}</div></div></div>`;}).join('');}
function tabContent(s){if(state.tab==='instances')return `<div class="detail-section"><div class="section-heading"><h3>Observed instances</h3><span>${s.scopes.length} exact ${s.scopes.length===1?'path':'paths'}</span></div><p class="callout">These are observed files. A discovered file does not by itself prove that an agent loaded it.</p><div class="instance-list">${instanceRows(s)}</div></div>`;
  if(state.tab==='source')return `<div class="detail-section"><div class="section-heading"><h3>Source &amp; provenance</h3></div><p class="callout"><strong>What is known:</strong> this demo record represents a local folder. A source URL alone would not prove the installed content is current.</p><div class="source-row"><span>Source type</span><span>${escapeHtml(s.source)}</span></div><div class="source-row"><span>Primary path</span><span>${escapeHtml(pathFor(s.scopes[0],s.name))}</span></div><div class="source-row"><span>Observed date</span><span>${escapeHtml(s.updated)}</span></div><div class="source-row"><span>Revision</span><span>Not recorded in demo</span></div><p class="subtle-note">No update action is offered without a verified source comparison.</p></div>`;
  if(state.tab==='content')return `<div class="detail-section"><div class="section-heading"><h3>Skill document</h3><span>sample text</span></div><article class="prose"><h4>When to use</h4><p>${escapeHtml(s.description)}</p><h4>Instructions</h4><p>${escapeHtml(s.body)}</p><h4>File</h4><div class="code-line">${escapeHtml(pathFor(s.scopes[0],s.name))}</div></article></div>`;
  const finding=s.state==='divergent'?`<p class="callout"><strong>Copies disagree.</strong> The Claude Code copy differs from the selected copy. Compare exact instances before syncing or editing.</p>`:s.state==='invalid'?`<p class="callout"><strong>Needs repair.</strong> The observed file has invalid frontmatter in this sample. Open Instances to find the exact path.</p>`:`<p class="callout"><strong>Observed in ${s.scopes.length} ${s.scopes.length===1?'scope':'scopes'}.</strong> The copies shown here match in this sample. Check Instances for their exact paths.</p>`;
  return `<div class="detail-section">${finding}<div class="section-heading"><h3>At a glance</h3><span>observed evidence</span></div><div class="proof-grid"><div class="proof-cell"><strong>${s.scopes.length}</strong><span>Observed ${s.scopes.length===1?'copy':'copies'}</span></div><div class="proof-cell"><strong>${(s.tokens/1000).toFixed(1)}k</strong><span>Estimated tokens</span></div><div class="proof-cell"><strong>${s.state==='divergent'?'2':s.state==='invalid'?'1':'0'}</strong><span>${s.state==='divergent'?'Content variants':s.state==='invalid'?'Validation finding':'Findings'}</span></div></div><p class="mini-heading">Where this skill appears</p><div class="instance-list">${instanceRows(s)}</div><button class="button button-quiet" style="margin-top:16px" type="button" data-open-tab="instances">Inspect all instances ${icon('arrow-right')}</button></div>`;}
function renderDetail(){if(!visibleSkills().some(item=>item.name===state.selected)){ $('#detail-content').innerHTML='<div class="detail-inner"><p class="overline">Library / detail</p><h2 id="detail-title">No matching skill selected</h2><p class="subtle-note">Choose a visible skill to inspect its copies and source information.</p></div>';return;}let s=skills.find(item=>item.name===state.selected);$('#detail-content').innerHTML=`<div class="detail-inner"><div class="detail-topline"><span class="breadcrumb">Library / ${escapeHtml(s.name)}</span><span>Sample document</span></div><div class="detail-heading"><div><h2 id="detail-title">${escapeHtml(s.name)}</h2><p>${escapeHtml(s.description)}</p></div><div class="detail-actions"><button class="button button-quiet" type="button" id="copy-path">${icon('copy')} Copy path</button><button class="button button-quiet" type="button" id="validate-skill">${icon('check')} Validate</button></div></div><div class="detail-meta"><span>State &nbsp; ${status(s.state)}</span><span>Scopes &nbsp; <strong>${s.scopes.map(escapeHtml).join(', ')}</strong></span><span>Updated &nbsp; <strong>${escapeHtml(s.updated)}</strong></span></div><div class="detail-tabs" role="tablist" aria-label="Skill details">${[['overview','Overview'],['instances','Instances'],['source','Source'],['content','Content']].map(([id,label])=>`<button class="detail-tab ${state.tab===id?'is-active':''}" type="button" role="tab" id="tab-${id}" aria-controls="detail-panel" aria-selected="${state.tab===id}" data-tab="${id}">${label}</button>`).join('')}</div><div id="detail-panel" role="tabpanel" aria-labelledby="tab-${state.tab}">${tabContent(s)}</div><div id="detail-notice" role="status"></div></div>`;}
function renderOtherView(){const view=state.view;const headings={overview:['Workspace overview','A clear view of the skills on disk.'],quality:['Quality evidence','Inspect validation and content differences.'],recovery:['Recovery','Review what could be restored.']};const [title,subtitle]=headings[view];let body=view==='recovery'?`<p class="callout" style="max-width:720px">This prototype has no recovery artifacts. In the product, recovery actions require an explicit review before any file changes.</p>`:`<div class="overview-grid"><div><strong>${skills.length}</strong><span>Logical skills</span></div><div><strong>${skills.reduce((n,s)=>n+s.scopes.length,0)}</strong><span>Observed instances</span></div><div><strong>2</strong><span>Need attention</span></div></div><div class="overview-list"><button type="button" data-jump="design-system"><span>Review divergent copies of <strong>design-system</strong></span><span>Open in Library →</span></button><button type="button" data-jump="release-checklist"><span>Inspect invalid <strong>release-checklist</strong></span><span>Open in Library →</span></button></div>`;$('#main').insertAdjacentHTML('beforeend',`<section class="overview-screen" id="other-view"><p class="overline">${view==='overview'?'Local workspace':escapeHtml(view)}</p><h1>${title}</h1><p>${subtitle} This screen uses illustrative data for the first design prototype.</p>${body}</section>`);}
function render(){renderScopes();renderList();renderDetail();$('#main').classList.toggle('show-detail',false);$('#other-view')?.remove();const isLibrary=state.view==='library';$('#library-pane').hidden=!isLibrary;$('#detail-pane').hidden=!isLibrary;if(!isLibrary)renderOtherView();document.querySelectorAll('.rail-nav').forEach(btn=>{let active=btn.dataset.view===state.view;btn.classList.toggle('is-active',active);if(active)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');});}
function setView(view){state.view=view;render();setStatus(`${view[0].toUpperCase()+view.slice(1)} · sample workspace`);}
function selectSkill(name){state.selected=name;state.tab='overview';if(state.view!=='library')state.view='library';render();$('#main').classList.add('show-detail');if(matchMedia('(max-width: 760px)').matches)$('#mobile-back').focus();setStatus(`${name} selected`);}
document.addEventListener('click',event=>{const scope=event.target.closest('[data-scope]');if(scope){state.scope=scope.dataset.scope;renderScopes();renderList();renderDetail();setStatus(`Showing ${state.scope}`);return;}const filter=event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;renderList();renderDetail();setStatus(`Filter: ${filter.textContent.trim()}`);return;}const skill=event.target.closest('[data-skill]');if(skill){selectSkill(skill.dataset.skill);return;}const tab=event.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderDetail();$(`#tab-${state.tab}`).focus();return;}const openTab=event.target.closest('[data-open-tab]');if(openTab){state.tab=openTab.dataset.openTab;renderDetail();$(`#tab-${state.tab}`).focus();return;}const nav=event.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return;}const jump=event.target.closest('[data-jump]');if(jump){selectSkill(jump.dataset.jump);return;}if(event.target.closest('#clear-filters')){state.scope='All scopes';state.filter='all';state.query='';$('#search').value='';renderScopes();renderList();renderDetail();setStatus('Filters cleared');return;}if(event.target.closest('#copy-path')){const selected=skills.find(s=>s.name===state.selected);const path=pathFor(selected.scopes[0],selected.name);if(navigator.clipboard?.writeText){navigator.clipboard.writeText(path).then(()=>setStatus('Sample path copied')).catch(()=>setStatus(`Sample path: ${path}`));}else setStatus(`Sample path: ${path}`);return;}if(event.target.closest('#validate-skill')){const selected=skills.find(s=>s.name===state.selected);$('#detail-notice').innerHTML=`<div class="inline-notice ${selected.state==='invalid'?'error':''}">${selected.state==='invalid'?'Sample validation: frontmatter needs repair.':'Sample validation: no structural errors found.'}</div>`;setStatus(`Sample validation shown for ${selected.name}`);return;}});
$('#search').addEventListener('input',event=>{state.query=event.target.value.trim().toLowerCase();if(state.view!=='library')state.view='library';render();});
$('#mobile-scope').addEventListener('change',event=>{state.scope=event.target.value;renderScopes();renderList();renderDetail();});
$('#mobile-back').addEventListener('click',()=>{$('#main').classList.remove('show-detail');document.querySelector(`[data-skill="${CSS.escape(state.selected)}"]`)?.focus();});
$('#theme-trigger').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;$('#theme-trigger').setAttribute('aria-label',`Switch to ${state.theme==='light'?'dark':'light'} theme`);$('#theme-trigger').innerHTML=icon(state.theme==='light'?'moon':'sun');setStatus(`${state.theme==='light'?'Light':'Dark'} theme`);});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#create-dialog').open){event.preventDefault();$('#search').focus();}if(event.key==='Escape'&&$('#main').classList.contains('show-detail')&&!$('#create-dialog').open){$('#mobile-back').click();}});
const dialog=$('#create-dialog');const nameField=$('#skill-name');const descriptionField=$('#skill-description');
function clearErrors(){[nameField,descriptionField].forEach(field=>field.removeAttribute('aria-invalid'));$('#name-error').textContent='';$('#description-error').textContent='';}
$('#create-trigger').addEventListener('click',()=>{clearErrors();$('#create-form').reset();dialog.showModal();nameField.focus();});
$('#dialog-close').addEventListener('click',()=>dialog.close());$('#create-cancel').addEventListener('click',()=>dialog.close());
$('#create-form').addEventListener('submit',event=>{event.preventDefault();clearErrors();const name=nameField.value.trim();const description=descriptionField.value.trim();let valid=true;if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(name)){nameField.setAttribute('aria-invalid','true');$('#name-error').textContent='Use lowercase letters, numbers, and single hyphens.';valid=false;}else if(skills.some(s=>s.name===name)) {nameField.setAttribute('aria-invalid','true');$('#name-error').textContent='A skill with this name is already in the sample library.';valid=false;}if(!description){descriptionField.setAttribute('aria-invalid','true');$('#description-error').textContent='Enter a short description.';valid=false;}if(!valid){(nameField.getAttribute('aria-invalid')?nameField:descriptionField).focus();return;}skills.push({name,description,state:'active',scopes:['Codex'],tokens:0,source:'Prototype draft',updated:'Just now',body:description});dialog.close();state.view='library';state.scope='All scopes';state.filter='all';state.query='';$('#search').value='';state.selected=name;state.tab='overview';render();setStatus(`Sample skill ${name} added in memory`);document.querySelector(`[data-skill="${CSS.escape(name)}"]`)?.focus();});
render();
